CREATE TABLE projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE experiments (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, parameters JSON NOT NULL, metrics JSON NOT NULL, notes TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE datasets (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE dataset_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, dataset_id BIGINT NOT NULL, version INT NOT NULL, filename VARCHAR(255) NOT NULL, sha256 CHAR(64) NOT NULL, original_file LONGBLOB NOT NULL, fields_json JSON NOT NULL, rows_json JSON NOT NULL, warnings_json JSON NOT NULL, row_count INT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(dataset_id,version), FOREIGN KEY(dataset_id) REFERENCES datasets(id));
CREATE TABLE charts (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, revision INT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE chart_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, chart_id BIGINT NOT NULL, dataset_version_id BIGINT NOT NULL, version INT NOT NULL, schema_version INT NOT NULL, config_json JSON NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(chart_id,version), FOREIGN KEY(chart_id) REFERENCES charts(id), FOREIGN KEY(dataset_version_id) REFERENCES dataset_versions(id));
